import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(
  entities = [PatientEntity::class, AncVisitEntity::class, DangerSignEntity::class],
  version = 1
)
abstract class AncDatabase : RoomDatabase() {
  abstract fun patientDao(): PatientDao
  abstract fun ancVisitDao(): AncVisitDao
  abstract fun dangerSignDao(): DangerSignDao

  companion object {
    @Volatile private var instance: AncDatabase? = null

    fun getInstance(context: Context): AncDatabase =
      instance ?: synchronized(this) {
        instance ?: Room.databaseBuilder(
          context.applicationContext,
          AncDatabase::class.java,
          "anc_database"
        ).build().also { instance = it }
      }
  }
}

