package com.example.ancapp.network

import com.google.gson.JsonObject
import com.squareup.retrofit2.Retrofit
import com.squareup.retrofit2.converter.gson.GsonConverterFactory
import com.squareup.retrofit2.http.GET
import com.squareup.retrofit2.http.Path
import com.squareup.retrofit2.http.Query

interface FhirApi {
  @GET("Patient")
  suspend fun getPatients(): JsonObject

  @GET("Patient/{id}")
  suspend fun getPatient(@Path("id") id: String): JsonObject

  @GET("Encounter")
  suspend fun getEncounters(@Query("patient") patientId: String): JsonObject

  @GET("Observation")
  suspend fun getObservations(@Query("subject") patientId: String): JsonObject

  @GET("Questionnaire/anc-contact")
  suspend fun getAncQuestionnaire(): JsonObject
}

object FhirServiceFactory {
  private const val BASE_URL = "http://10.0.2.2:8080/fhir/"

  fun createFhirService(): FhirApi {
    val retrofit = Retrofit.Builder()
      .baseUrl(BASE_URL)
      .addConverterFactory(GsonConverterFactory.create())
      .build()
    return retrofit.create(FhirApi::class.java)
  }
}

