@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientEntity>,
  onPatientSelected: (String) -> Unit,
  onSync: () -> Unit,
  isLoading: Boolean,
  modifier: Modifier = Modifier
) {
  Scaffold(
    topBar = {
      CenterAlignedTopAppBar(
        title = { Text("Pregnant Patients") },
        actions = {
          Button(
            onClick = onSync,
            enabled = !isLoading,
            modifier = Modifier.padding(end = 8.dp)
          ) {
            Text("Sync")
          }
        }
      )
    },
    modifier = modifier
  ) { paddingValues ->
    LazyColumn(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues)
        .padding(8.dp),
      verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
      items(patients) { patient ->
        PatientCard(patient = patient, onClick = { onPatientSelected(patient.id) })
      }
    }
  }
}

@Composable
fun PatientCard(patient: PatientEntity, onClick: () -> Unit) {
  Card(
    modifier = Modifier
      .fillMaxWidth()
      .clickable(onClick = onClick),
    elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
  ) {
    Column(modifier = Modifier.padding(16.dp)) {
      Text(patient.name, fontSize = 18.sp, fontWeight = FontWeight.Bold)
      Text("Age: ${calculateAge(patient.dateOfBirth)} years")
      Text(
        "Due: ${patient.estimatedDueDate.format(DateTimeFormatter.ofPattern("MMM d, yyyy"))}",
        fontSize = 14.sp,
        color = MaterialTheme.colorScheme.secondary
      )
      val weeksPregnant = calculateWeeksPregnant(patient.dateOfBirth, patient.estimatedDueDate)
      Text(
        "$weeksPregnant weeks pregnant",
        fontSize = 14.sp,
        color = MaterialTheme.colorScheme.tertiary
      )
    }
  }
}

