import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import com.example.ancapp.viewmodel.AncViewModel
import java.time.LocalDate

sealed class Screen {
  data object Register : Screen()
  data class PatientDetail(val patientId: String) : Screen()
  data class NewVisit(val patientId: String, val patientName: String) : Screen()
}

@Composable
fun AncApp(viewModel: AncViewModel, modifier: Modifier = Modifier) {
  var currentScreen by remember { mutableStateOf<Screen>(Screen.Register) }
  val patients by viewModel.patients.collectAsState()
  val selectedPatient by viewModel.selectedPatient.collectAsState()
  val isLoading by viewModel.isLoading.collectAsState()

  when (val screen = currentScreen) {
    is Screen.Register -> {
      RegisterScreen(
        patients = patients,
        onPatientSelected = { patientId ->
          viewModel.selectPatient(patientId)
          currentScreen = Screen.PatientDetail(patientId)
        },
        onSync = { viewModel.syncPatientsFromServer() },
        isLoading = isLoading,
        modifier = modifier
      )
    }

    is Screen.PatientDetail -> {
      if (selectedPatient != null) {
        PatientDetailScreen(
          patientWithVisits = selectedPatient!!,
          onBackClick = { currentScreen = Screen.Register },
          onAddVisitClick = {
            currentScreen = Screen.NewVisit(selectedPatient!!.patient.id, selectedPatient!!.patient.name)
          },
          modifier = modifier
        )
      }
    }

    is Screen.NewVisit -> {
      NewVisitFormScreen(
        patientId = screen.patientId,
        patientName = screen.patientName,
        onBackClick = { currentScreen = Screen.PatientDetail(screen.patientId) },
        onSaveVisit = { date, weeks, weight, sys, dias, hgb, notes, signs ->
          viewModel.recordAncVisit(
            patientId = screen.patientId,
            visitDate = date,
            gestationalAgeWeeks = weeks,
            weightKg = weight,
            systolicBp = sys,
            diastolicBp = dias,
            hemoglobinGdl = hgb,
            notes = notes,
            dangerSigns = signs
          )
          currentScreen = Screen.PatientDetail(screen.patientId)
        },
        modifier = modifier
      )
    }
  }
}

