package com.example.ancapp.network

import com.google.gson.Gson
import com.google.gson.JsonObject
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.net.URL

class FhirApi {
  private val gson = Gson()
  private val baseUrl = "http://10.0.2.2:8080/fhir"

  suspend fun getPatients(): JsonObject = withContext(Dispatchers.IO) {
    fetchJson("$baseUrl/Patient")
  }

  suspend fun getPatient(id: String): JsonObject = withContext(Dispatchers.IO) {
    fetchJson("$baseUrl/Patient/$id")
  }

  suspend fun getEncounters(patientId: String): JsonObject = withContext(Dispatchers.IO) {
    fetchJson("$baseUrl/Encounter?patient=$patientId")
  }

  suspend fun getObservations(patientId: String): JsonObject = withContext(Dispatchers.IO) {
    fetchJson("$baseUrl/Observation?subject=$patientId")
  }

  suspend fun getAncQuestionnaire(): JsonObject = withContext(Dispatchers.IO) {
    fetchJson("$baseUrl/Questionnaire/anc-contact")
  }

  private fun fetchJson(urlString: String): JsonObject {
    return try {
      val url = URL(urlString)
      val connection = url.openConnection()
      connection.connectTimeout = 5000
      connection.readTimeout = 5000
      val response = connection.inputStream.bufferedReader().use { it.readText() }
      gson.fromJson(response, JsonObject::class.java)
    } catch (e: Exception) {
      e.printStackTrace()
      JsonObject()
    }
  }
}

object FhirServiceFactory {
  fun createFhirService(): FhirApi {
    return FhirApi()
  }
}

